sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var del_records = [{
            table: 'x_hccc_hoc_ohs_h_and_v_negotiated_resolution',
            id: current.getValue('negotiated_resolution')
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_investigation',
            id: current.getValue('investigation')
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_mediation',
            id: current.getValue('mediation')
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_preventative_measures',
            id: current.getValue('preventative_meaures')
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_initial_review',
            id: current.getValue('initial_review')
        },
        {
            table: 'x_hccc_hoc_ohs_h_and_v_rw',
            id: current.getValue('rw')
        }

    ];

    for (var i = 0; i < del_records.length; i++) {
        var gr = new GlideRecord(del_records[i].table.toString());

        gr.addQuery('sys_id', del_records[i].id.toString());
        gr.query();

        if (gr.next()) {
            gr.deleteRecord();
        }
    }

})(current, previous);
